'use strict';

const CR = 13;
const LF = 10;
const QUOTE = 34;
const SPACE = 32;
const BOM = 0xfeff;

// Parser states.
const RECORD_START = 0; // nothing of the current record consumed yet
const FIELD_START = 1; // at the first character of a field
const UNQUOTED = 2; // inside a field that did not start with `"`
const QUOTED = 3; // inside a quoted field
const QUOTE_IN_QUOTED = 4; // just read a `"` inside a quoted field

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function normalizeOptions(options) {
  if (options === undefined || options === null) return {};
  if (typeof options !== 'object') throw new TypeError('options must be an object');
  return options;
}

function checkDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
  return delimiter;
}

function setKey(obj, key, value) {
  if (key === '__proto__') {
    Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
  } else {
    obj[key] = value;
  }
}

// Incremental parser shared by `parse` and `createParser`. Every character is
// consumed exactly once; all state needed to resume mid-field, mid-escape or
// between CR and LF lives on the instance.
class Parser {
  constructor(options) {
    options = normalizeOptions(options);
    this.delimiter = checkDelimiter(options.delimiter).charCodeAt(0);
    this.header = options.header === true;
    this.skipEmptyLines = options.skipEmptyLines === true;

    this.columns = null; // header names, once the header record is complete
    this.seen = this.header ? new Set() : null; // header names read so far

    this.state = RECORD_START;
    this.started = false; // whether any input has been seen (for the BOM)
    this.line = 1; // position of the next character
    this.col = 1;
    this.afterCR = false; // last consumed character was CR, so LF completes CRLF
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldCol = 1;

    this.record = [];
    this.field = '';
    this.out = [];
  }

  feed(s) {
    const n = s.length;
    if (n === 0) return;
    let i = 0;
    if (!this.started) {
      this.started = true;
      if (s.charCodeAt(0) === BOM) i = 1;
    }
    const delimiter = this.delimiter;

    while (i < n) {
      const c = s.charCodeAt(i);
      switch (this.state) {
        case RECORD_START:
          if (this.afterCR) {
            this.afterCR = false;
            if (c === LF) {
              i++;
              continue;
            }
          }
          if (this.skipEmptyLines && (c === CR || c === LF)) {
            i++;
            this.newline(c);
            continue;
          }
          this.recordLine = this.line;
          this.state = FIELD_START;
        // falls through
        case FIELD_START:
          this.fieldLine = this.line;
          this.fieldCol = this.col;
          if (c === QUOTE) {
            i++;
            this.col++;
            this.state = QUOTED;
            continue;
          }
          if (c === delimiter) {
            i++;
            this.col++;
            this.endField();
            continue;
          }
          if (c === CR || c === LF) {
            i++;
            this.newline(c);
            this.endField();
            this.endRecord();
            continue;
          }
          this.state = UNQUOTED;
        // falls through
        case UNQUOTED: {
          let j = i;
          while (j < n) {
            const d = s.charCodeAt(j);
            if (d === delimiter || d === CR || d === LF) break;
            j++;
          }
          if (j > i) {
            this.field += s.slice(i, j);
            this.col += j - i;
            i = j;
          }
          if (i === n) continue;
          const d = s.charCodeAt(i);
          i++;
          if (d === delimiter) {
            this.col++;
            this.endField();
            this.state = FIELD_START;
          } else {
            this.newline(d);
            this.endField();
            this.endRecord();
          }
          continue;
        }
        case QUOTED: {
          let j = i;
          let line = this.line;
          let col = this.col;
          let afterCR = this.afterCR;
          while (j < n) {
            const d = s.charCodeAt(j);
            if (d === QUOTE) break;
            if (d === CR) {
              line++;
              col = 1;
              afterCR = true;
            } else {
              if (d === LF) {
                if (!afterCR) {
                  line++;
                  col = 1;
                }
              } else {
                col++;
              }
              afterCR = false;
            }
            j++;
          }
          if (j > i) this.field += s.slice(i, j);
          this.line = line;
          this.col = col;
          this.afterCR = afterCR;
          i = j;
          if (i < n) {
            i++;
            this.col++;
            this.afterCR = false;
            this.state = QUOTE_IN_QUOTED;
          }
          continue;
        }
        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            i++;
            this.col++;
            this.field += '"';
            this.state = QUOTED;
            continue;
          }
          if (c === delimiter) {
            i++;
            this.col++;
            this.endField();
            this.state = FIELD_START;
            continue;
          }
          if (c === CR || c === LF) {
            i++;
            this.newline(c);
            this.endField();
            this.endRecord();
            continue;
          }
          throw new CsvError('Unexpected character after closing quote', this.line, this.col);
      }
    }
  }

  finish() {
    switch (this.state) {
      case RECORD_START:
        break;
      case FIELD_START:
        this.fieldLine = this.line;
        this.fieldCol = this.col;
        this.endField();
        this.endRecord();
        break;
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        this.endField();
        this.endRecord();
        break;
      case QUOTED:
        // A quoted field starts with its opening quote.
        throw new CsvError('Unclosed quoted field', this.fieldLine, this.fieldCol);
    }
  }

  take() {
    const out = this.out;
    this.out = [];
    return out;
  }

  // Advance the position past a line break outside a quoted field. It is never
  // the LF of a CRLF: that is consumed in RECORD_START.
  newline(c) {
    this.line++;
    this.col = 1;
    this.afterCR = c === CR;
  }

  endField() {
    const field = this.field;
    this.field = '';
    if (this.seen !== null) {
      if (this.seen.has(field)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(field)}`, this.fieldLine, this.fieldCol);
      }
      this.seen.add(field);
    }
    this.record.push(field);
  }

  endRecord() {
    const record = this.record;
    this.record = [];
    this.state = RECORD_START;
    if (!this.header) {
      this.out.push(record);
      return;
    }
    const columns = this.columns;
    if (columns === null) {
      this.columns = record;
      this.seen = null;
      return;
    }
    if (record.length !== columns.length) {
      throw new CsvError(
        `Expected ${columns.length} field${columns.length === 1 ? '' : 's'} but found ${record.length}`,
        this.recordLine,
        1
      );
    }
    const obj = {};
    for (let k = 0; k < columns.length; k++) setKey(obj, columns[k], record[k]);
    this.out.push(obj);
  }
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  const parser = new Parser(options);
  parser.feed(text);
  parser.finish();
  return parser.take();
}

function createParser(options = {}) {
  const parser = new Parser(options);
  let finished = false;

  function run(step) {
    if (finished) throw new Error('Parser has already finished');
    try {
      step();
    } catch (err) {
      finished = true;
      throw err;
    }
    return parser.take();
  }

  return {
    write(chunk) {
      return run(() => {
        if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
        parser.feed(chunk);
      });
    },
    end() {
      return run(() => {
        finished = true;
        parser.finish();
      });
    },
  };
}

function toText(value) {
  switch (typeof value) {
    case 'string':
      return value;
    case 'number':
    case 'boolean':
      return String(value);
    case 'undefined':
      return '';
    default:
      if (value === null) return '';
      throw new TypeError(`Cannot write a value of type ${typeof value}`);
  }
}

function needsQuotes(text, delimiter) {
  const n = text.length;
  if (n === 0) return false;
  if (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE) return true;
  for (let i = 0; i < n; i++) {
    const c = text.charCodeAt(i);
    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
  }
  return false;
}

function quote(text) {
  return `"${text.replace(/"/g, '""')}"`;
}

function stringify(rows, options = {}) {
  options = normalizeOptions(options);
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  const delimiter = checkDelimiter(options.delimiter);
  const delimiterCode = delimiter.charCodeAt(0);

  let eol = options.eol;
  if (eol === undefined) eol = '\r\n';
  else if (eol !== '\r\n' && eol !== '\n') throw new TypeError('eol must be "\\r\\n" or "\\n"');

  let header = options.header;
