describe('trim option', () => {
  const trim = { trim: true };

  it('is off by default', () => {
    assert.deepEqual(parse(' a , b\t,\t"c" '.replace(' "c" ', '"c"')), [[' a ', ' b\t', '\t"c"']]);
    assert.deepEqual(parse(' a ', { trim: false }), [[' a ']]);
    assert.deepEqual(parse(' a ', { trim: 1 }), [[' a ']]);
  });

  it('removes spaces and tabs from both ends of unquoted fields', () => {
    assert.deepEqual(parse(' a , \tb c\t ,\t\t,   \r\n x\t', trim), [
      ['a', 'b c', '', ''],
      ['x'],
    ]);
    assert.deepEqual(parse(' ', trim), [['']]);
    assert.deepEqual(parse('a, ', trim), [['a', '']]);
  });

  it('does not touch other whitespace', () => {
    assert.deepEqual(parse(' a ,\fb\f', trim), [[' a ', '\fb\f']]);
  });

  it('allows spaces and tabs around quoted fields and keeps their content exactly', () => {
    assert.deepEqual(parse(' "  a ""b"" \t" \t,\t"c"  \n"d" ', trim), [
      ['  a "b" \t', 'c'],
      ['d'],
    ]);
    assert.deepEqual(parse('  "a\r\n b "  ,x', trim), [['a\r\n b ', 'x']]);
    assert.deepEqual(parse('a, ""  ', trim), [['a', '']]);
  });

  it('treats a quote after leading spaces as an opening quote', () => {
    assert.deepEqual(parse('  "a,b"', trim), [['a,b']]);
    assert.deepEqual(parse('  a"b"', trim), [['a"b"']]);
    assertCsvError(() => parse('a,  "b', trim), 1, 5);
    assertCsvError(() => parse('x\n "b', trim), 2, 2);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" b', trim), 1, 5);
    assertCsvError(() => parse('"a" "b"', trim), 1, 5);
    assertCsvError(() => parse('"a"\t"', trim), 1, 5);
    assertCsvError(() => parse('"a" x', { ...trim, delimiter: ';' }), 1, 5);
  });

  it('does not allow whitespace around quotes without trim', () => {
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
    assertCsvError(() => parse('"a" '), 1, 4);
  });

  it('lets a tab or space delimiter win over trimming', () => {
    assert.deepEqual(parse(' a\t b \t', { ...trim, delimiter: '\t' }), [['a', 'b', '']]);
    assert.deepEqual(parse('a  "b" \tc\t', { ...trim, delimiter: ' ' }), [['a', '', 'b', '\tc\t'.trim() && '\tc']]);
  });

  it('trims header names and detects duplicates after trimming', () => {
    assert.deepEqual(parse(' x , y \n 1,"2 "', { ...trim, header: true }), [{ x: '1', y: '2 ' }]);
    assertCsvError(() => parse('a, a', { ...trim, header: true }), 1, 3);
  });

  it('agrees with createParser for every split', () => {
    const inputs = [' a , "b" ,\t', '  "x\r\n"  \r\n\t y', '"a" ', '"a" x', '  "a', ' ', 'a,\t', '\t"a"\t"b"', '"a""" \r', ' "" '];
    for (const options of [trim, { ...trim, header: true }, { ...trim, skipEmptyLines: true }, { ...trim, delimiter: '\t' }]) {
      for (const input of inputs) {
        const expected = outcome(() => parse(input, options));
        for (let i = 0; i <= input.length; i++) {
          for (let j = i; j <= input.length; j++) {
            const chunks = [input.slice(0, i), input.slice(i, j), input.slice(j)];
            assert.deepEqual(
              outcome(() => streamParse(chunks, options)),
              expected,
              `input ${JSON.stringify(input)} chunks ${JSON.stringify(chunks)} options ${JSON.stringify(options)}`
            );
          }
        }
      }
