});

describe('comment option', () => {
  const comment = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\nb'), [['#a'], ['b']]);
    assert.deepEqual(parse('#a', { comment: undefined }), [['#a']]);
  });

  it('skips a whole line including its line break', () => {
    assert.deepEqual(parse('#one\na,b\n#two, "unclosed\r\nc\n#three\r#four\n#last', comment), [
      ['a', 'b'],
      ['c'],
    ]);
    assert.deepEqual(parse('#a', comment), []);
    assert.deepEqual(parse('#a\r\n#b\r\n', comment), []);
    assert.deepEqual(parse('a\r\n#b\r\nc', comment), [['a'], ['c']]);
  });

  it('is not an empty line and never becomes a record', () => {
    assert.deepEqual(parse('#\na\n#', comment), [['a']]);
    assert.deepEqual(parse('a\n\n#x\n', comment), [['a'], ['']]);
    assert.deepEqual(parse('a\n\n#x\n', { ...comment, skipEmptyLines: true }), [['a']]);
    assert.deepEqual(parse('#x\r\n\r\ny', comment), [[''], ['y']]);
  });

  it('is ordinary anywhere but the first character of a line', () => {
    assert.deepEqual(parse('a#,#b\n c#\n"#x"\n"a\n#b"', comment), [['a#', '#b'], [' c#'], ['#x'], ['a\n#b']]);
    assert.deepEqual(parse(' #a', { ...comment, trim: true }), [['#a']]);
    assert.deepEqual(parse('a,\n#b', comment), [['a', '']]);
  });

  it('works with header mode', () => {
    assert.deepEqual(parse('#c\nx,y\n#c\n1,2\n#c', { ...comment, header: true }), [{ x: '1', y: '2' }]);
  });

  it('keeps counting comment lines in error positions', () => {
    assertCsvError(() => parse('#a\r\n#b\n#c\r"x', comment), 4, 1);
    assertCsvError(() => parse('#a\n"b"c', comment), 2, 4);
    assertCsvError(() => parse('#a\r\nx\r\n#b\r\ny,z', { ...comment, header: true }), 4, 1);
    assertCsvError(() => parse('#a\nx,x', { ...comment, header: true }), 2, 3);
  });

  it('supports other characters, including a space', () => {
    assert.deepEqual(parse(';a\nb', { comment: ';' }), [['b']]);
    assert.deepEqual(parse(' a\nb', { comment: ' ' }), [['b']]);
    assert.deepEqual(parse('#a\n;b\nc', { comment: ';', delimiter: '|' }), [['#a'], ['c']]);
