  it('is validated', () => {
    for (const bad of [null, '', '##', ',', '"', '\r', '\n', 1, true, {}, '😀']) {
      assert.throws(() => parse('a', { comment: bad }), TypeError, JSON.stringify(bad));
      assert.throws(() => createParser({ comment: bad }), TypeError);
