    assert.deepEqual(parse(' x , y \n 1,"2 "', { ...trim, header: true }), [{ x: '1', y: '2 ' }]);
    assertCsvError(() => parse('a, a', { ...trim, header: true }), 1, 3);
  });

  it('agrees with createParser for every split', () => {
    const inputs = [' a , "b" ,\t', '  "x\r\n"  \r\n\t y', '"a" ', '"a" x', '  "a', ' ', 'a,\t', '\t"a"\t"b"', '"a""" \r', ' "" '];
    assertSplitsMatch(inputs, [trim, { ...trim, header: true }, { ...trim, skipEmptyLines: true }, { ...trim, delimiter: '\t' }]);
  });
});

describe('comment option', () => {
  const comment = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\nb'), [['#a'], ['b']]);
    assert.deepEqual(parse('#a', { comment: undefined }), [['#a']]);
  });

  it('skips a whole line including its line break', () => {
    assert.deepEqual(parse('#one\na,b\n#two, "unclosed\r\nc\n#three\r#four\n#last', comment), [['a', 'b'], ['c']]);
    assert.deepEqual(parse('#a', comment), []);
    assert.deepEqual(parse('#a\r\n#b\r\n', comment), []);
    assert.deepEqual(parse('a\r\n#b\r\nc', comment), [['a'], ['c']]);
  });

  it('is not an empty line and never becomes a record', () => {
    assert.deepEqual(parse('#\na\n#', comment), [['a']]);
    assert.deepEqual(parse('a\n\n#x\n', comment), [['a'], ['']]);
    assert.deepEqual(parse('a\n\n#x\n', { ...comment, skipEmptyLines: true }), [['a']]);
    assert.deepEqual(parse('#x\r\n\r\ny', comment), [[''], ['y']]);
  });

  it('is ordinary anywhere but the first character of a line', () => {
    assert.deepEqual(parse('a#,#b\n c#\n"#x"\n"a\n#b"', comment), [['a#', '#b'], [' c#'], ['#x'], ['a\n#b']]);
    assert.deepEqual(parse(' #a', { ...comment, trim: true }), [['#a']]);
    assert.deepEqual(parse('a,\n#b', comment), [['a', '']]);
  });

  it('works with header mode', () => {
    assert.deepEqual(parse('#c\nx,y\n#c\n1,2\n#c', { ...comment, header: true }), [{ x: '1', y: '2' }]);
  });

  it('keeps counting comment lines in error positions', () => {
    assertCsvError(() => parse('#a\r\n#b\n#c\r"x', comment), 4, 1);
    assertCsvError(() => parse('#a\n"b"c', comment), 2, 4);
    assertCsvError(() => parse('#a\r\nx\r\n#b\r\ny,z', { ...comment, header: true }), 4, 1);
    assertCsvError(() => parse('#a\nx,x', { ...comment, header: true }), 2, 3);
  });

  it('supports other characters, including a space', () => {
    assert.deepEqual(parse(';a\nb', { comment: ';' }), [['b']]);
    assert.deepEqual(parse(' a\nb', { comment: ' ' }), [['b']]);
    assert.deepEqual(parse('#a\n;b\nc', { comment: ';', delimiter: '|' }), [['#a'], ['c']]);
  });

  it('is validated', () => {
    for (const bad of [null, '', '##', ',', '"', '\r', '\n', 1, true, {}, '😀']) {
      assert.throws(() => parse('a', { comment: bad }), TypeError, JSON.stringify(bad));
      assert.throws(() => createParser({ comment: bad }), TypeError);
    }
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.throws(() => createParser({ comment: '\t', delimiter: '\t' }), TypeError);
  });

  it('agrees with createParser for every split', () => {
    const inputs = ['#a\r\nb', 'a\r#b\r\n\nc', '#', '#\n#\r\n#\r', 'a#\n#"\n"#', '\ufeff#a\nb', 'x,y\n#z\n1,2\n#', '#a\r\r\nb'];
    assertSplitsMatch(inputs, [comment, { ...comment, header: true }, { ...comment, skipEmptyLines: true }, { ...comment, trim: true }]);
  });

  it('agrees with createParser on random inputs and chunkings, with trim too', () => {
    const random = mulberry32(99);
    const alphabet = ['a', ',', '"', '"', '\r', '\n', ' ', '\t', '#', '\ufeff'];
    for (let round = 0; round < 4000; round++) {
      let input = '';
      const length = Math.floor(random() * 20);
      for (let k = 0; k < length; k++) input += alphabet[Math.floor(random() * alphabet.length)];
      const chunks = [];
      for (let start = 0; start < input.length; ) {
        const size = Math.floor(random() * 5);
        chunks.push(input.slice(start, start + size));
        start += size;
      }
      const options = {
        header: random() < 0.3,
        skipEmptyLines: random() < 0.5,
        trim: random() < 0.6,
        delimiter: random() < 0.2 ? '\t' : ',',
      };
      if (random() < 0.7) options.comment = '#';
      assert.deepEqual(
        outcome(() => streamParse(chunks, options)),
        outcome(() => parse(input, options)),
        `chunks ${JSON.stringify(chunks)} options ${JSON.stringify(options)}`
      );
    }
  });
});

